package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.hardware.DigitalChannel;
import com.qualcomm.robotcore.hardware.HardwareMap;
import com.qualcomm.robotcore.hardware.VoltageSensor;
import com.qualcomm.robotcore.util.Range;

import org.firstinspires.ftc.teamcode.config.DeviceNames;
import org.firstinspires.ftc.teamcode.config.Tuned;

// Generated by refract-suite ftc-construct. One motor gear-linked to both turrets; angle from its motor
// encoder (as DECODE). Angles are in FRONT-turret degrees; the back turret follows by its own ratio.
// Control: position error x kP -> turn-rate command (+ feedforward rate) -> power = kS + kV x rate,
// battery compensated. All numbers come from the Yaw Tuner (G-1). DECODE's kA term (under 2% power) and
// braking prediction are dropped: kP is set by the tuner for no overshoot instead.
public class Yaw {
    // control-design choices, not robot measurements
    private static final double ANGLE_ALPHA = 0.8;
    private static final double VELOCITY_ALPHA = 0.8;
    // kS fades in over the rate kP gives for this much error. DECODE switched kS fully on above 0.5 deg/s,
    // which made the turret hunt left/right at rest (32008's own notes).
    private static final double KS_FADE_DEG = 1.0;
    private static final double MIN_VOLTAGE = 8.0;
    // the index switch is only trusted when passed slowly: at 15 deg/s a 20 ms loop sees it at most 0.3 deg late
    public static final double INDEX_MAX_DEG_S = 15;
    // turning by hand moves less than a count per loop, so speed and direction come from this window
    private static final double INDEX_WINDOW_S = 0.1;

    private final DcMotorEx motor;
    private final HardwareMap hardwareMap;
    // optional magnetic switch at forward (DeviceNames.YAW_INDEX); null without it
    private final DigitalChannel index;
    // the encoder count that reads 0 deg; static so it carries from the auto into TeleOp, like the encoder count
    private static int zeroTicks = 0;
    private boolean indexWasOn, indexed, indexTooFast;
    private int indexRefRaw = Integer.MIN_VALUE, indexLastRaw = Integer.MIN_VALUE, indexMoveDir = 0;
    private long indexRefNs;
    private boolean started = false;
    private long lastNanos = 0, lastVoltageNanos = 0;
    private double filteredDeg, lastRawDeg, filteredRate;
    private double voltage = 12.0;

    public Yaw(HardwareMap hardwareMap) {
        this.hardwareMap = hardwareMap;
        motor = hardwareMap.get(DcMotorEx.class, DeviceNames.YAW);
        motor.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
        motor.setMode(DcMotor.RunMode.RUN_WITHOUT_ENCODER);
        index = hardwareMap.tryGet(DigitalChannel.class, DeviceNames.YAW_INDEX);
        if (index != null) index.setMode(DigitalChannel.Mode.INPUT);
    }

    // Both turrets facing front. Encoder reset only, no motion (legal in INIT).
    public void zero() {
        motor.setMode(DcMotor.RunMode.STOP_AND_RESET_ENCODER);
        motor.setMode(DcMotor.RunMode.RUN_WITHOUT_ENCODER);
        zeroTicks = 0;
        indexed = false;
        started = false;
    }

    // the index switch is there and program 3 measured where it turns on
    public boolean hasIndex() {
        return index != null && Tuned.isSet(Tuned.yawIndexDeg, Tuned.yawTicksPerDegFront);
    }

    // Homing: the turret reads currentDeg by this count but is really at trueDeg. Moves the zero so frontDeg() reads
    // trueDeg here (shiftDeg = currentDeg - trueDeg). The tracking filter starts over.
    public void shiftZeroDeg(double shiftDeg) {
        zeroTicks += (int) Math.round(shiftDeg * Tuned.yawTicksPerDegFront);
        started = false;
    }

    // Homing is done: the tracking filter starts over
    public void homed() {
        indexed = false;
        started = false;
    }

    // the switch is in the configuration (program 3 measures it)
    public boolean indexPresent() {
        return index != null;
    }

    // the switch sees the magnet (a REV magnetic limit switch reads false then)
    public boolean atIndex() {
        return index != null && !index.getState();
    }

    // INIT, every loop. By eye, "straight forward" is good to a degree or two; the switch is the same every time.
    // The moment it turns on while the turret turns left, the yaw reads Tuned.yawIndexDeg there. True once done.
    public boolean indexZero() {
        if (!hasIndex()) return false;
        int raw = motor.getCurrentPosition();
        long now = System.nanoTime();
        boolean on = atIndex();
        // which way it last moved: slowly, a count can be several loops apart, so not just this loop's change
        if (indexLastRaw != Integer.MIN_VALUE && raw != indexLastRaw) {
            indexMoveDir = (raw - indexLastRaw) * Tuned.yawTicksPerDegFront > 0 ? 1 : -1;
        }
        indexLastRaw = raw;
        if (on && !indexWasOn && indexRefRaw != Integer.MIN_VALUE) {
            double degPerS = Math.abs((raw - indexRefRaw) / Tuned.yawTicksPerDegFront) / Math.max(1e-3, (now - indexRefNs) / 1e9);
            indexTooFast = degPerS > INDEX_MAX_DEG_S;
            if (indexMoveDir > 0 && !indexTooFast) {
                zeroTicks = raw - (int) Math.round(Tuned.yawIndexDeg * Tuned.yawTicksPerDegFront);
                indexed = true;
                started = false;
            }
        }
        indexWasOn = on;
        if (indexRefRaw == Integer.MIN_VALUE || now - indexRefNs >= INDEX_WINDOW_S * 1e9) {
            indexRefRaw = raw;
            indexRefNs = now;
        }
        return indexed;
    }

    // the last pass over the switch was too fast to trust
    public boolean indexTooFast() {
        return indexTooFast && !indexed;
    }

    public static boolean calibrated() {
        return Tuned.isSet(Tuned.yawTicksPerDegFront, Tuned.yawTicksPerDegBack, Tuned.yawMinDeg, Tuned.yawMaxDeg);
    }

    public static boolean tuned() {
        return calibrated() && Tuned.isSet(Tuned.yawKs, Tuned.yawKv, Tuned.yawPowerSign, Tuned.yawTuningVoltage, Tuned.yawKp);
    }

    public int ticks() {
        return motor.getCurrentPosition() - zeroTicks;
    }

    public double frontDeg() {
        return ticks() / Tuned.yawTicksPerDegFront;
    }

    public double backDeg() {
        return ticks() / Tuned.yawTicksPerDegBack;
    }

    public static double backToFrontDeg(double backDeg) {
        return backDeg * Tuned.yawTicksPerDegBack / Tuned.yawTicksPerDegFront;
    }

    public static double frontToBackDeg(double frontDeg) {
        return frontDeg * Tuned.yawTicksPerDegFront / Tuned.yawTicksPerDegBack;
    }

    public static boolean inLimits(double frontDeg) {
        return frontDeg >= Tuned.yawMinDeg && frontDeg <= Tuned.yawMaxDeg;
    }

    // targetFrontDeg: wanted front-turret angle relative to the robot. rateFeedforwardDeg: deg/s the
    // turret must turn just to stay on target (chassis spin cancellation + line-of-sight rate).
    public void track(double targetFrontDeg, double rateFeedforwardDeg) {
        if (!tuned() || Double.isNaN(targetFrontDeg)) {
            motor.setPower(0);
            return;
        }
        long now = System.nanoTime();
        double dt = lastNanos == 0 ? 0 : (now - lastNanos) / 1e9;
        lastNanos = now;
        double raw = frontDeg();
        if (!started || dt <= 1e-4) {
            filteredDeg = raw;
            lastRawDeg = raw;
            filteredRate = 0;
            started = true;
            motor.setPower(0);
            return;
        }
        filteredDeg = ANGLE_ALPHA * raw + (1 - ANGLE_ALPHA) * filteredDeg;
        filteredRate = VELOCITY_ALPHA * (raw - lastRawDeg) / dt + (1 - VELOCITY_ALPHA) * filteredRate;
        lastRawDeg = raw;

        double target = Range.clip(targetFrontDeg, Tuned.yawMinDeg, Tuned.yawMaxDeg);
        // Gear play (E-6): the encoder is on the motor and the turret can rest up to half the play either side of it.
        // Which side depends on the turret (pushed along = behind, its own momentum after braking = ahead) and cannot
        // be seen from the encoder, so no side is guessed: aiming at the target itself keeps the miss within half the
        // play either way (a wrong guess doubles it).
        double rateCommand = Tuned.yawKp * (target - filteredDeg) + rateFeedforwardDeg;
        double fadeRate = Tuned.yawKp * KS_FADE_DEG;
        double ksScale = fadeRate > 0 ? Math.min(1, Math.abs(rateCommand) / fadeRate) : 1;
        double power = (Math.signum(rateCommand) * Tuned.yawKs * ksScale + Tuned.yawKv * rateCommand)
                * Tuned.yawTuningVoltage / voltage();
        motor.setPower(Range.clip(Tuned.yawPowerSign * power, -1, 1));
    }

    public double rate() {
        return filteredRate;
    }

    // Cut power but keep filter state, so tracking resumes without a jump (DECODE freeze-on-lock).
    public void hold() {
        motor.setPower(0);
    }

    public void stop() {
        motor.setPower(0);
        started = false;
    }

    // Yaw Tuner part A: let the turrets be turned by hand.
    public void setFloat(boolean free) {
        motor.setZeroPowerBehavior(free ? DcMotor.ZeroPowerBehavior.FLOAT : DcMotor.ZeroPowerBehavior.BRAKE);
    }

    // Raw power for the Yaw Tuner only.
    public void setRawPower(double power) {
        motor.setPower(Range.clip(power, -1, 1));
    }

    public double voltage() {
        long now = System.nanoTime();
        if (now - lastVoltageNanos > 250_000_000L) {
            double max = 0;
            for (VoltageSensor sensor : hardwareMap.voltageSensor) max = Math.max(max, sensor.getVoltage());
            voltage = Math.max(MIN_VOLTAGE, max > 0 ? max : voltage);
            lastVoltageNanos = now;
        }
        return voltage;
    }
}
